157	        currentOwner.setCity(ownerFieldsDto.getCity());
158	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
159	        currentOwner.setLastName(ownerFieldsDto.getLastName());
160	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
161	        String email = ownerFieldsDto.getEmail();
162	        if (email != null) {
163	            email = email.trim().toLowerCase(Locale.ROOT);
164	            if (!EMAIL_PATTERN.matcher(email).matches()) {
165	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
166	            }
167	        }
168	        currentOwner.setEmail(email);
169	        this.clinicService.saveOwner(currentOwner);
170	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
