225	        Visit visit = visitMapper.toVisit(visitFieldsDto);
226	        Pet pet = new Pet();
227	        pet.setId(petId);
228	        visit.setPet(pet);
229	        this.clinicService.saveVisit(visit);
230	        VisitDto visitDto = visitMapper.toVisitDto(visit);
