236	
237	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
238	    @Override
239	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
240	        Owner owner = this.clinicService.findOwnerById(ownerId);
241	        if (owner != null) {
242	            Pet pet = owner.getPet(petId);
243	            if (pet != null) {
244	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
245	            }
246	        }
247	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
248	    }
249	
250	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
251	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
252	
253	    /**
254	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
255	     * code are kept when present; otherwise country code '+61' is assumed and a single
256	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
257	     * stripped. The result must be a '+' followed by 8 to 15 digits.
258	     * Returns {@code null} when the number cannot form a valid E.164 value.
259	     */
260	    private static String normalizeTelephone(String telephone) {
261	        if (telephone == null) {
262	            return null;
263	        }
264	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
265	        String e164;
266	        if (cleaned.startsWith("+")) {
267	            e164 = cleaned;
268	        } else {
269	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
270	            e164 = "+61" + national;
271	        }
272	        return E164_PATTERN.matcher(e164).matches() ? e164 : null;
273	    }
274	
275	    /**
276	     * Build the customer code '<LAST3>-<NNNN>': LAST3 is the upper-cased first three letters
277	     * of {@code lastName} and NNNN is a global 4-digit zero-padded sequence equal to one more
278	     * than the current number of owners (e.g. 'SMI-0007').
279	     */
280	    private String generateCustomerCode(String lastName) {
281	        String letters = lastName.replaceAll("[^\\p{L}]", "");
282	        String last3 = letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
283	        int sequence = this.clinicService.findAllOwners().size() + 1;
284	        return String.format("%s-%04d", last3, sequence);
285	    }
286	
287	    /** Whether any existing owner already uses the given (E.164) telephone number. */
288	    private boolean isTelephoneInUse(String telephone) {
289	        return this.clinicService.findAllOwners().stream()
290	            .map(Owner::getTelephone)
291	            .filter(existing -> existing != null)
292	            .map(OwnerRestControllerV1::normalizeTelephone)
293	            .filter(existing -> existing != null)
294	            .anyMatch(telephone::equals);
295	    }
296	
297	    /** Common street-type abbreviations expanded during address normalization. */
298	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
299	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
300	
301	    /**
302	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
303	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
304	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
305	     * string when {@code address} is null or blank after normalization.
306	     */
307	    private static String normalizeAddress(String address) {
308	        if (address == null) {
309	            return "";
310	        }
311	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
312	        if (collapsed.isEmpty()) {
313	            return "";
314	        }
315	        StringBuilder sb = new StringBuilder(collapsed.length());
316	        for (String token : collapsed.split(" ")) {
317	            if (sb.length() > 0) {
318	                sb.append(' ');
319	            }
320	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
321	        }
322	        return sb.toString();
323	    }
324	
325	    /**
326	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
327	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
328	     */
329	    private static String normalizeHouseholdField(String value) {
330	        if (value == null) {
331	            return "";
332	        }
333	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
334	    }
335	
336	    /**
337	     * Existing owners that share {@code owner}'s household, i.e. have the same last name AND the
338	     * same address compared case-insensitively with collapsed whitespace.
339	     */
340	    private List<Owner> findHousemates(Owner owner) {
341	        String lastName = normalizeHouseholdField(owner.getLastName());
342	        String address = normalizeHouseholdField(owner.getAddress());
343	        return this.clinicService.findAllOwners().stream()
344	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
345	                && normalizeHouseholdField(existing.getAddress()).equals(address))
346	            .toList();
347	    }
348	
349	    /**
350	     * Whether any existing owner already shares the same household as {@code owner}, i.e. has the
351	     * same last name AND the same address compared case-insensitively with collapsed whitespace.
352	     */
353	    private boolean isHouseholdInUse(Owner owner) {
354	        return !findHousemates(owner).isEmpty();
355	    }
356	
357	    /**
358	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
359	     * same last name and address (compared case-insensitively with collapsed whitespace). Derived
360	     * deterministically from those normalized fields so housemates always resolve to the same value,
361	     * regardless of registration order.
362	     */
363	    private static String householdId(Owner owner) {
364	        String key = normalizeHouseholdField(owner.getLastName()) + "\n"
365	            + normalizeHouseholdField(owner.getAddress());
366	        try {
367	            byte[] digest = MessageDigest.getInstance("SHA-256")
368	                .digest(key.getBytes(StandardCharsets.UTF_8));
369	            StringBuilder sb = new StringBuilder(24);
370	            for (int i = 0; i < 12; i++) {
371	                sb.append(String.format("%02X", digest[i]));
372	            }
373	            return sb.toString();
374	        }
375	        catch (NoSuchAlgorithmException e) {
376	            throw new IllegalStateException("SHA-256 not available", e);
377	        }
378	    }
379	}
